/**
 * Shared generation and delivery for every emailed one-time code.
 *
 * Extracted so the OTP, email-verification and password-reset providers cannot
 * drift apart on the two things that matter: how the code is generated, and
 * whether it ever reaches a log.
 */

const DIGITS = 8;

/**
 * 8 cryptographically random digits, generated by REJECTION SAMPLING.
 *
 * The previous implementation did `bytes[i] % 10`. With 256 byte values that is
 * biased: 0-5 each arise from 26 byte values, 6-9 from only 25. The bias is
 * small but free to remove, and biased "random" in an auth primitive is the kind
 * of thing that is embarrassing to explain later. Values >= 250 are discarded so
 * the remaining range is an exact multiple of 10.
 */
export function generateNumericCode(length = DIGITS): string {
  let out = "";
  const buf = new Uint8Array(length * 2);
  while (out.length < length) {
    crypto.getRandomValues(buf);
    for (const b of buf) {
      if (b >= 250) continue;
      out += (b % 10).toString();
      if (out.length === length) break;
    }
  }
  return out;
}

/**
 * True when the deployment has a real mail transport configured.
 *
 * Gates the dev fallback below. Codes are only ever logged when there is no
 * other way for a developer to receive them.
 */
export function hasMailTransport(): boolean {
  return Boolean(
    process.env.SMTP_HOST ||
      process.env.RESEND_API_KEY ||
      process.env.OLLASTACK_MAIL_TOKEN,
  );
}

import { internal } from "./_generated/api";
import { buildAuthEmail } from "./emailTemplates";

type Ctx = {
  runAction: (ref: unknown, args: unknown) => Promise<unknown>;
  runMutation?: (ref: unknown, args: unknown) => Promise<unknown>;
  // @convex-dev/auth actually hands `sendVerificationRequest` a full ActionCtx
  // (GenericActionCtxWithAuthConfig), so this is available at runtime — it is
  // optional here only so the type stays honest for callers that pass less.
  runQuery?: (ref: unknown, args: unknown) => Promise<unknown>;
};

/**
 * Email a code, and log it ONLY when no transport exists.
 *
 * This closes a real production leak. Previously every OTP, verification and
 * reset code was written to the Convex log stream unconditionally, so anyone who
 * could read deployment logs could authenticate as any user — a full
 * authentication bypass that leaves no trace in the auth events. The codes were
 * genuinely harvestable from the live deployment.
 *
 * The fallback survives only for local development, where SMTP_HOST and
 * RESEND_API_KEY are both unset and there is no inbox to read.
 */
export async function deliverCode(
  ctx: Ctx | undefined,
  label: string,
  email: string,
  token: string,
  sendEmail: unknown,
  /**
   * The library's own expiry for this code, passed straight through from
   * `sendVerificationRequest`. Rendering THIS rather than a copy of `maxAge`
   * is what stops the email ever claiming a duration the backend does not
   * enforce.
   */
  expires?: Date,
): Promise<void> {
  // The per-email send budget is NOT consumed here any more (audit F-07). By
  // the time delivery runs the code has already been replaced, so throttling
  // here suppressed the email but not the swap. Every caller now consumes the
  // budget in the transaction that issues the code (auth.ts callback, and the
  // account-deletion code), and a throttled request never reaches this line.
  //
  // Development-only code logging, and only on EXPLICIT opt-in (audit §14): a
  // deployment that merely lacks mail variables must not start writing live
  // authentication codes to its log stream.
  if (!hasMailTransport() && process.env.AUTH_LOG_CODES === "1") {
    console.warn(`[auth] ${label} code for ${email}: ${token}`);
  }
  // A greeting is a nicety, never a precondition. Resolved AFTER the throttle
  // so a suppressed send costs no read, and swallowed on failure because an
  // auth email must never fail over how it says hello. `deliverCode` only knows
  // an address — a magic-OTP sign-in can precede any user row — so an absent
  // name simply drops the greeting line rather than guessing one.
  let name: string | null = null;
  if (ctx && typeof ctx.runQuery === "function") {
    try {
      name = (await ctx.runQuery(internal.users.nameByEmail, {
        email,
      })) as string | null;
    } catch {
      name = null;
    }
  }

  const mail = buildAuthEmail({ label, code: token, expires, name });

  try {
    await ctx?.runAction(sendEmail, {
      to: email,
      subject: mail.subject,
      // Both parts, always. The HTML is the presentation; the text is what
      // keeps the code usable if a client strips it, and is the shape the
      // provider's OTP extractor already recognises.
      text: mail.text,
      html: mail.html,
    });
  } catch (e) {
    // Never include the token in an error path.
    console.warn(`[email] ${label} send failed: ${(e as Error).message}`);
  }
}
